module chassis() {
    color("gray")
    cube([150, 100, 10], center=true);
}

// Wheels
module wheel() {
    color("black")
    rotate([0, 90, 0])
    cylinder(r=30, h=10, center=true);
}

// Ultrasonic Sensor
module sensor() {
    color("blue")
    cube([10, 40, 20], center=true);
}

// Battery/Controller
module box(size, color_val) {
    color(color_val)
    cube(size, center=true);
}

// Assembly
union() {
    // Chassis
    chassis();

    // Wheels
    translate([-40, 55, 0]) wheel();
    translate([-40, -55, 0]) wheel();

    // Caster wheel
    translate([60, 0, -15]) color("silver") sphere(r=15);

    // Sensor
    translate([80, 0, 10]) sensor();

    // Arduino/Driver
    translate([0, 0, 15]) box([60, 40, 20], "red");
    translate([20, 0, 15]) box([40, 40, 20], "green");
}
